/// <summary>
/// This class handles the dialog for attribute group change on Item Group in Rebate module
/// </summary>
internal class METTAMRebateItemGroupAttributeChangeDialog extends Runbase
{
    DialogRunbase dialog;

    DialogField   dlguseItemAttributes;
    DialogField   dlgProductPriceAttributeGroup;

    boolean                         useItemAttributes;
    METGUPPricingAttributeGroupName productPriceAttributeGroup;
    TAMRebateGroup                  METTamRebateGroup;

    public const int CurrentVersion = 1;

    #localmacro.CurrentList
        useItemAttributes,
        productPriceAttributeGroup
    #endmacro

}

Method.Source:
/// <summary>
/// Overridden to not allow batch processing
/// </summary>
/// <returns>true if batch processing is allowed</returns>
boolean canGoBatch()
{
    return false;
}

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <returns>dialog object</returns>
    public Object dialog()
    {
        dialog = super();

        dialog.alwaysOnTop(true);

        dlguseItemAttributes    = dialog.addField(ExtendedTypeStr(NoYesId),"@MET:UseItemAttribute");
        dlguseItemAttributes.value(METTamRebateGroup.METuseItemAttributes);

        //Override modified method for dlguseItemAttributes
        dlguseItemAttributes.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METTAMRebateItemGroupAttributeChangeDialog, dialogUseItemAttribute_modified), this);

        dlgProductPriceAttributeGroup = dialog.addField(extendedTypeStr(GUPPricingAttributeGroupName));
        //override lookup method for dlgProductPriceAttributeGroup
        dlgProductPriceAttributeGroup.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METTAMRebateItemGroupAttributeChangeDialog, lookupProductPriceAttribute), this);
        if(METTamRebateGroup.METuseItemAttributes)
        {
            dlgProductPriceAttributeGroup.value(strFmt("@MET:P1",METTamRebateGroup.METGUPProductPricingAttributeGroup));
        }
        else
        {
            dlgProductPriceAttributeGroup.enabled(false);
        }

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    boolean getFromDialog()
    {
        boolean ret = true;

        useItemAttributes           = dlguseItemAttributes.value();
        productPriceAttributeGroup  = dlgProductPriceAttributeGroup.value();
        
        return ret;
    }

/// <summary>
/// standard Pack method
/// </summary>
/// <returns>container</returns>
public container pack()
{
    // pack() and unpack() methods are used to load the last value from user
    return [CurrentVersion,#CurrentList];
}

    /// <summary>
    /// standard unpack method
    /// </summary>
    /// <param name = "packedClass">container</param>
    /// <returns>true if retrieved successfully</returns>
    public boolean unpack(container packedClass)
    {
        Integer version     = RunBase::getVersion(packedClass);

        switch (version)
        {
            case CurrentVersion:
                [version,#CurrentList] = packedClass;
                break;
            default :
                return false;
        }
        return true;
    }

/// <summary>
/// parm method for getting/setting TAMRebateGroup object
/// </summary>
/// <param name = "_tamRebateGroup">table object</param>
/// <returns>table object</returns>
public TAMRebateGroup parmTAMRebateGroup(TAMRebateGroup _tamRebateGroup = METTamRebateGroup)
{
    METTamRebateGroup = _tamRebateGroup;
    return METTamRebateGroup;
}

    /// <summary>
    /// This will update the ueItemAttributes and the Product Price attribute Group name as selected by user
    /// </summary>
    public void run()
    {
        #OCCRetryCount

        if(METTamRebateGroup.METGUPProductPricingAttributeGroup != productPriceAttributeGroup ||
                METTamRebateGroup.METuseItemAttributes != useItemAttributes)
        {
            try
            {
                ttsbegin;
                METTamRebateGroup.selectForUpdate(true);
                METTamRebateGroup.METGUPProductPricingAttributeGroup  = productPriceAttributeGroup;
                METTamRebateGroup.METuseItemAttributes                = useItemAttributes;
                METTamRebateGroup.update();
                ttscommit;
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error (strFmt("@MET:RebateGroupAttributeAssignError", productPriceAttributeGroup));
                    error("@Subledger:DeadlockErrorThrown");
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        error (strFmt("@MET:RebateGroupAttributeAssignError", productPriceAttributeGroup));
                        error("@Subledger:UpdateConflictErrorThrown");
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    error (strFmt("@MET:RebateGroupAttributeAssignError", productPriceAttributeGroup));
                    error("@Subledger:UpdateConflictErrorThrown");
                }
            }
            catch
            {
                error (strFmt("@MET:RebateGroupAttributeAssignError", productPriceAttributeGroup));
            }
        }
    }

    /// <summary>
    /// Validation to check if product attribute is properly assigned
    /// </summary>
    /// <param name = "calledFrom">object </param>
    /// <returns>true if all validations are passed</returns>
    public boolean validate(Object calledFrom = null)
    {
        boolean ret;
    
        ret = super(calledFrom);

        //do any validation here
        if(dlguseItemAttributes.value() == NoYes::Yes && dlgProductPriceAttributeGroup.value() == '')
        {
            ret = checkFailed("@MET:ProductAttributeGroupNameMandatory");
        }
        else if (dlguseItemAttributes.value() == NoYes::Yes)
        {
            GUPPricingAttributeGroup pricingGroup;
            select firstonly * from pricingGroup
                where   pricingGroup.Name       == dlgProductPriceAttributeGroup.value() &&
                        pricingGroup.GroupType  == GUPPricingAttributeGroupType::Product;

            if(!pricingGroup.RecId)
            {
                ret = checkFailed(strFmt("@MET:InvalidProductAttributeGroupName",dlgProductPriceAttributeGroup.value()));
            }

        }
    
        return ret;
    }

/// <summary>
/// Dialog Description
/// </summary>
/// <returns>Dialog Description text</returns>
client server static ClassDescription description()
{
    return "@MET:ChangeProductAttributes";
}

    /// <summary>
    /// Entry point method of the operation
    /// </summary>
    /// <param name = "_args">Args</param>
    public static void main(Args _args)
    {
        //Check if the Args.Record() has the same TableID as the Table Buffer(TAMRebateGroup).
        if  (_args && _args.record().TableId == tableNum(TAMRebateGroup))
        {
            //Assign the args records to table buffer and then pass it to salesLine_ds(FormDataSource)
            TAMRebateGroup rebateGroup  = _args.record();
 
            //Call Method which will be used to create the Dialog
            METTAMRebateItemGroupAttributeChangeDialog dialogRebateItemGroupAttributeChangeDialog = new METTAMRebateItemGroupAttributeChangeDialog();
            dialogRebateItemGroupAttributeChangeDialog.parmTAMRebateGroup(rebateGroup);
            
            if(dialogRebateItemGroupAttributeChangeDialog.prompt())
            {
                dialogRebateItemGroupAttributeChangeDialog.runOperation();//updateRebateGroupAttributeDetails(rebateGroup);

                FormDataSource TAMRebateGroup_ds   = FormDataUtil::getFormDataSource(rebateGroup);
                TAMRebateGroup_ds.executeQuery();
            }
        }
    }

/// <summary>
/// Construct and return the class object
/// </summary>
/// <returns>class object</returns>
public static METTAMRebateItemGroupAttributeChangeDialog construct()
{
    return new METTAMRebateItemGroupAttributeChangeDialog();
}

/// <summary>
/// Protected constructor method
/// </summary>
protected void new()
{
    super();
}

    /// <summary>
    /// disable controls on Dialog form if record need to be deleted
    /// </summary>
    /// <param name = "_dlguseItemAttributes">use item attribute dialog control</param>
    /// <returns>alwyas true</returns>
    private boolean dialogUseItemAttribute_modified(FormCheckBoxControl _dlguseItemAttributes)
    {
        if(_dlguseItemAttributes)
        {
            if (dlguseItemAttributes.value() == true)
            {
                dlgProductPriceAttributeGroup.enabled(true);
            }
            else
            {
                dlgProductPriceAttributeGroup.enabled(false);
                dlgProductPriceAttributeGroup.value('');
            }
        }

        return true;
    }

    /// <summary>
    /// product pricing attribute group lookup
    /// </summary>
    /// <param name = "_formControl">attribute group field control</param>
    private void lookupProductPriceAttribute(FormControl _formControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbdsPricingAttributeGroup;
        SysTableLookup          sysTableLookup;

        if (_formControl != null)
        {
            // Create an instance of SysTableLookup with
            // the current calling form control.

            sysTableLookup = SysTableLookup::newParameters(tablenum(GUPPricingAttributeGroup), _formControl);
            sysTableLookup.addLookupfield(fieldnum(GUPPricingAttributeGroup, Name), true);
            sysTableLookup.addLookupfield(fieldnum(GUPPricingAttributeGroup, Description),false);
            sysTableLookup.addLookupfield(fieldnum(GUPPricingAttributeGroup, GroupType), false);
            
            qbdsPricingAttributeGroup = query.addDataSource(tableNum(GUPPricingAttributeGroup));
            qbdsPricingAttributeGroup.addSortField(fieldnum(GUPPricingAttributeGroup, Name),SortOrder::Ascending);

            QueryBuildRange  qbrGroupType = qbdsPricingAttributeGroup.addRange(fieldNum(GUPPricingAttributeGroup,GroupType));
            qbrGroupType.status(1);
            qbrGroupType.value(SysQuery::value(GUPPricingAttributeGroupType::Product));
            sysTableLookup.parmUseLookupValue(false);

            sysTableLookup.parmQuery(query);

            // Perform the lookup.
            sysTableLookup.performFormLookup();
        }
    }

/// <summary>
/// Disabled multiple dialogs in different sessions
/// </summary>
/// <returns>false</returns>
protected boolean canRunInNewSession()
{
    return false;
}
